local nav={}local _world=nil local _player=nil function nav.init(deps)_world=deps.world _player=deps.player end local STEP=1 local REBUILD_DIST=2.0 local REBUILD_DIST_SQ=REBUILD_DIST*REBUILD_DIST local WALK_Y_START=10 local WALK_Y_SEARCH=12 local DIRS={{STEP,0},{-STEP,0},{0,STEP},{0,-STEP}}local function packDir(ddx,ddz)return(ddx+1)*3+(ddz+1)end local function unpackDir(p)local ddx=math.floor(p/3)-1 local ddz=(p%3)-1 return ddx,ddz end local flowField={}local flowOrigin={x=nil,z=nil}local walkCache={}function nav.snap(v)return math.floor(v/STEP+0.5)*STEP end function nav.isWalkable(wx,wz)local kx=wx+1000 local kz=wz+1000 local col=walkCache[kx]if col then local cached=col[kz]if cached~=nil then return cached end else walkCache[kx]={}col=walkCache[kx]end local groundY=_world.findGroundBelow(wx,WALK_Y_START,wz,WALK_Y_SEARCH)local result=false if groundY then if not _world.isBlockSolid(wx,groundY,wz)and not _world.isBlockSolid(wx,groundY+1,wz)then result=true end end col[kz]=result return result end function nav.invalidateArea(bounds)local x1=nav.snap(bounds.minX)-STEP local z1=nav.snap(bounds.minZ)-STEP local x2=nav.snap(bounds.maxX)+STEP local z2=nav.snap(bounds.maxZ)+STEP for wx=x1,x2,STEP do local kx=wx+1000 local col=walkCache[kx]if col then for wz=z1,z2,STEP do col[wz+1000]=nil end end end end function nav.clearCache()walkCache={}flowField={}flowOrigin={x=nil,z=nil}end function nav.buildFlowField()flowField={}local goalX=nav.snap(_player.x)local goalZ=nav.snap(_player.z)flowOrigin.x=_player.x flowOrigin.z=_player.z if not flowField[goalX]then flowField[goalX]={}end flowField[goalX][goalZ]=packDir(0,0)local queue={goalX,goalZ}local head=1 local visited={}visited[goalX*100003+goalZ]=true while head<=#queue do local cx=queue[head];head=head+1 local cz=queue[head];head=head+1 for _,dir in ipairs(DIRS)do local nx=cx+dir[1]local nz=cz+dir[2]local k=nx*100003+nz if not visited[k]then visited[k]=true if nav.isWalkable(nx,nz)then if not flowField[nx]then flowField[nx]={}end flowField[nx][nz]=packDir(cx-nx,cz-nz)queue[#queue+1]=nx queue[#queue+1]=nz end end end end end function nav.getFlowDir(wx,wz)local gx=nav.snap(wx)local gz=nav.snap(wz)local col=flowField[gx]if not col then return nil end local p=col[gz]if not p then return nil end return unpackDir(p)end function nav.update()if flowOrigin.x==nil then nav.buildFlowField()return end local dx=_player.x-flowOrigin.x local dz=_player.z-flowOrigin.z if dx*dx+dz*dz>=REBUILD_DIST_SQ then nav.buildFlowField()end end function nav.reset()nav.clearCache()flowField={}flowOrigin={x=nil,z=nil}end return nav